/**
 * Italian course outline (CEFR A1→C2): 6 levels × 6 chapters × 8 lessons = 288
 * lessons. Fixed navigation skeleton (level → chapter → lesson). Each lesson's
 * teaching content is generated by the LLM on first open and cached in the
 * shared DB, so each lesson costs tokens only once ever.
 *
 * Lesson ids are stable ("a1-1-1") and the flat order defines linear unlock.
 */

export interface Lesson {
  id: string;
  title: string;
  objective: string;
}
export interface Chapter {
  id: string;
  title: string;
  lessons: Lesson[];
}
export interface Level {
  level: "A1" | "A2" | "B1" | "B2" | "C1" | "C2";
  title: string;
  chapters: Chapter[];
}

function lv(level: Level["level"], title: string, chapters: [string, [string, string][]][]): Level {
  return {
    level,
    title,
    chapters: chapters.map(([chTitle, lessons], ci) => ({
      id: `${level.toLowerCase()}-${ci + 1}`,
      title: chTitle,
      lessons: lessons.map(([lTitle, objective], li) => ({
        id: `${level.toLowerCase()}-${ci + 1}-${li + 1}`,
        title: lTitle,
        objective,
      })),
    })),
  };
}

