/** Flat, ordered list of lesson ids — defines the linear-unlock sequence. */
export const ORDERED_LESSON_IDS: string[] = CURRICULUM.flatMap((lvl) =>
  lvl.chapters.flatMap((ch) => ch.lessons.map((l) => l.id)),
);

export const TOTAL_LESSONS = ORDERED_LESSON_IDS.length;

export interface LessonLocation {
  level: Level;
  chapter: Chapter;
  lesson: Lesson;
}

/** Look up a lesson (and its level/chapter) by id. */
export function findLesson(id: string): LessonLocation | null {
  for (const level of CURRICULUM) {
    for (const chapter of level.chapters) {
      const lesson = chapter.lessons.find((l) => l.id === id);
      if (lesson) return { level, chapter, lesson };
    }
  }
  return null;
}

/** Flat id → { id, title, objective } map (used by V3 lesson recommendations). */
export function lessonMetaMap(): Record<string, { id: string; title: string; objective: string }> {
  const out: Record<string, { id: string; title: string; objective: string }> = {};
  for (const level of CURRICULUM) {
    for (const chapter of level.chapters) {
      for (const lesson of chapter.lessons) {
        out[lesson.id] = { id: lesson.id, title: lesson.title, objective: lesson.objective };
      }
    }
  }
  return out;
}

/** Resolve completed lesson ids to their titles (for mastered-topics memory). */
export function titlesForIds(ids: string[]): string[] {
  return ids.map((id) => findLesson(id)?.lesson.title).filter((t): t is string => !!t);
}
